/** @param {NS} ns */
export async function main(ns) {
  const ownedServers = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns', 'nectar-net'];
  let target = null;
  let maxMoney = 0;

  // Find most profitable target
  for (const server of ownedServers) {
    const money = ns.getServerMaxMoney(server);
    if (money > maxMoney) {
      maxMoney = money;
      target = server;
    }
  }

  ns.tprint(`Target: ${target} with max money $${maxMoney / 1e6}m`);

  // Main farming loop
  while (true) {
    const currentMoney = ns.getServerMoneyAvailable(target);
    const securityLevel = ns.getServerSecurityLevel(target);
    const minSecurity = ns.getServerMinSecurityLevel(target);
    const maxMoney = ns.getServerMaxMoney(target);

    // Prioritize: reduce security first, then grow, then hack
    if (securityLevel > minSecurity + 1) {
      // Weaken if security is too high
      const weakenTime = ns.getWeakenTime(target);
      await ns.weaken(target);
    } else if (currentMoney < maxMoney * 0.95) {
      // Grow if money is below 95% of max
      const growTime = ns.getGrowTime(target);
      await ns.grow(target);
    } else {
      // Hack when security is low and money is full
      const hackTime = ns.getHackTime(target);
      await ns.hack(target);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const servers = [];
  const queue = ['home'];
  const visited = new Set(['home']);

  while (queue.length > 0) {
    const srv = queue.shift();
    servers.push(srv);
    const neighbors = ns.scan(srv);
    for (const n of neighbors) {
      if (!visited.has(n)) {
        visited.add(n);
        queue.push(n);
      }
    }
  }

  let target = 'n00dles';
  let maxMoney = 0;
  for (const srv of servers) {
    const m = ns.getServerMaxMoney(srv);
    if (m > maxMoney) {
      maxMoney = m;
      target = srv;
    }
  }

  ns.tprint(`Target: ${target} (max: ${maxMoney})`);

  while (true) {
    const money = ns.getServerMoneyAvailable(target);
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);

    if (sec > minSec + 0.05) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.95) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

